package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.SubtypeResolver;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class StdSubtypeResolver_collectAndResolveSubtypesByTypeId_TriageGen2Test {

    private StdSubtypeResolver resolver;
    private MapperConfig<?> mockConfig;
    private AnnotationIntrospector mockAi;
    private AnnotatedMember mockProperty;
    private JavaType mockBaseType;

    private static class Base {}
    private static class SubTypeA extends Base {}
    private static class SubTypeB extends Base {}
    private static class Unrelated {}

    @Before
    public void setUp() {
        resolver = new StdSubtypeResolver();
        mockConfig = mock(MapperConfig.class);
        mockAi = mock(AnnotationIntrospector.class);
        mockProperty = mock(AnnotatedMember.class);
        mockBaseType = mock(JavaType.class);

        when(mockConfig.getAnnotationIntrospector()).thenReturn(mockAi);
        when(mockBaseType.getRawClass()).thenReturn(Base.class);
    }

    @Test
    public void testCollectWithNoPropertyAndNoRegisteredSubtypes() {
        // Test the path where property is null and _registeredSubtypes is null
        when(mockAi.findSubtypes(any())).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        assertNotNull(result);
        // Should only contain the root type via _combineNamedAndUnnamed
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Base.class)));
    }

    @Test
    public void testCollectWithPropertySubtypes() {
        // Setup property to return subtypes via AnnotationIntrospector
        NamedType namedTypeA = new NamedType(SubTypeA.class, "A");
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(namedTypeA));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        List<NamedType> resultList = (List<NamedType>) result;
        assertTrue(resultList.stream().anyMatch(nt -> nt.getType().equals(SubTypeA.class)));
    }

    @Test
    public void testCollectWithRegisteredSubtypes() {
        // Register subtypes explicitly
        resolver.registerSubtypes(new NamedType(SubTypeB.class, "B"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        assertNotNull(result);
        List<NamedType> resultList = (List<NamedType>) result;
        assertTrue(resultList.stream().anyMatch(nt -> nt.getType().equals(SubTypeB.class)));
    }

    @Test
    public void testCollectWithPropertyAndRegisteredSubtypesCombined() {
        // Property provides SubTypeA, Registration provides SubTypeB
        NamedType namedTypeA = new NamedType(SubTypeA.class, "A");
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(namedTypeA));
        resolver.registerSubtypes(new NamedType(SubTypeB.class, "B"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        List<NamedType> resultList = (List<NamedType>) result;
        assertTrue(resultList.stream().anyMatch(nt -> nt.getType().equals(SubTypeA.class)));
        assertTrue(resultList.stream().anyMatch(nt -> nt.getType().equals(SubTypeB.class)));
    }

    @Test
    public void testRegisteredSubtypeNotAssignableToRoot() {
        // SubTypeB is a subtype of Base, but Unrelated is not.
        // Unrelated should be ignored by the isAssignableFrom check.
        resolver.registerSubtypes(new NamedType(Unrelated.class, "U"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        List<NamedType> resultList = (List<NamedType>) result;
        assertFalse(resultList.stream().anyMatch(nt -> nt.getType().equals(Unrelated.class)));
    }

    @Test
    public void testPropertyReturnsNullSubtypes() {
        // Test branch where ai.findSubtypes(property) returns null
        when(mockAi.findSubtypes(mockProperty)).thenReturn(null);
        resolver.registerSubtypes(new NamedType(SubTypeB.class, "B"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        List<NamedType> resultList = (List<NamedType>) result;
        // Should still contain registered subtype
        assertTrue(resultList.stream().anyMatch(nt -> nt.getType().equals(SubTypeB.class)));
    }

    @Test
    public void testDuplicateSubtypesHandling() {
        // Ensure that if same subtype is provided by both property and registration, it doesn't crash 
        // (handled by typesHandled Set)
        NamedType namedTypeA = new NamedType(SubTypeA.class, "A");
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(namedTypeA));
        resolver.registerSubtypes(namedTypeA);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        // The result size should be controlled by the combination logic and typesHandled
        assertTrue(result.size() >= 1);
    }
}
